WITH base AS (SELECT id, customer_id, device, browser, country, SUBSTRING(device, 1, 2) AS device_prefix FROM sessions WHERE started_at > DATE '2023-07-18' AND browser IS DISTINCT FROM 'Firefox'), joined AS (SELECT s.*, c.email, c.country AS customer_country FROM base s JOIN customers c ON s.customer_id <=> c.id), latest_match AS (SELECT s.*, top1.event_time, top1.duration_sec FROM joined s LEFT JOIN LATERAL (SELECT c.event_time, c.duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY device ORDER BY event_time, id) AS prev_event_time FROM latest_match), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), with_gaps_2 AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY country ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY country ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions_sessions), sessions_sessions_2 AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no_2 FROM with_gaps_2), eligible AS (SELECT s.* FROM sessions_sessions_2 s WHERE NOT EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_time < s.prev_event_time)), with_windows AS (SELECT *, DENSE_RANK() OVER (PARTITION BY country ORDER BY duration_sec DESC NULLS LAST) AS duration_sec_dense_rank, COUNT(duration_sec) OVER (PARTITION BY country ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_count_7d, STDDEV_SAMP(session_no) OVER w_running AS device_stddev_samp_session_no FROM eligible WINDOW w_running AS (PARTITION BY device)) SELECT s.id, s.customer_id, s.device, s.country, s.device_prefix, s.customer_country, s.event_time, s.duration_sec, s.session_no_2, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'GROUP_B' ELSE 'CORE' END AS device_zone, (SELECT AVG(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS avg_account_balance FROM with_windows s ORDER BY country NULLS LAST;
